from itertools import permutations

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            vec = (dc, dr)
            if vec in vectors:
                return False
            vectors.add(vec)
    return True

# Find all Costas arrays of order 7 with x[1]=1
n = 7
solutions = []
for perm in permutations(range(n)):
    if perm[1] == 1:  # x[1]=1
        if is_costas(perm):
            solutions.append(perm)

print(f"Found {len(solutions)} solutions")
for sol in solutions:
    print(list(sol))
